(()=>{(function(){"use strict";window.GenBIApp.renderShell("feature");let n=document.querySelector("#feature-program-list");n&&n.querySelectorAll(".program-slide-card").forEach(r=>{let o=r.querySelector("[data-program-icon]");o&&(o.innerHTML=window.GenBIApp.icon(o.dataset.programIcon||"sparkles","program-icon-svg"));let e=[];try{e=JSON.parse(r.dataset.programSlides||"[]").filter(Boolean)}catch{e=[]}if(e.length&&(r.style.setProperty("--program-bg-image",`url('${e[0]}')`),e.length>1&&!window.matchMedia("(prefers-reduced-motion: reduce)").matches)){let t=0;window.setInterval(()=>{t=(t+1)%e.length,r.style.setProperty("--program-bg-image",`url('${e[t]}')`)},4200)}})})();})();
